  "Χρήστης": "User",
  "🔒 Το NetWatch δεν κρατά και δεν δείχνει ποτέ τον κωδικό. Κάποιος που «ακούει» στο ίδιο Wi‑Fi όμως θα τον έβλεπε ολόκληρο.": "🔒 NetWatch never stores or shows the password. But someone “listening” on the same Wi‑Fi would see all of it.",
  "Κανένας 🎉": "None 🎉",
  "Συσκευή": "Device",
  "Υπηρεσία": "Service",
  "Κίνδυνος": "Risk",
  "Δεν έχω δει ακόμα υπηρεσίες (φαίνονται μόνο όσες χρησιμοποιούνται).": "I haven't seen any services yet (only ones in use show up).",
  "Πρωτόκολλα χωρίς κρυπτογράφηση (πακέτα)": "Unencrypted protocols (packets)",
  "Βαθμός ασφάλειας του δικτύου σου": "Your network's security score",
  "Βγαίνει από ό,τι έχει δει το NetWatch: επιθέσεις, κωδικούς χωρίς κρυπτογράφηση, επικίνδυνες υπηρεσίες, άγνωστες συσκευές, HTTP και DNS χωρίς κρυπτογράφηση.": "Based on what NetWatch has seen: attacks, unencrypted passwords, risky services, unknown devices, unencrypted HTTP and DNS.",
  "Έλεγχοι": "Checks",
  "Κωδικοί χωρίς κρυπτογράφηση": "Unencrypted passwords",
  "Υπηρεσίες που «ακούν» στο LAN — επιφάνεια επίθεσης": "Services “listening” on the LAN — attack surface",
  "Ο έλεγχος είναι παθητικός: βλέπει μόνο ό,τι περνά από το δίκτυο. Για πλήρη εικόνα σκάναρε το δικό σου δίκτυο με": "The audit is passive: it only sees what passes over the network. For the full picture, scan your own network with",
  "Επιθέσεις": "Attacks",
  "Ποια επίθεση περιγράφει αυτό;": "Which attack does this describe?",
  "Θύρες": "Ports",
  "Ποια υπηρεσία ακούει συνήθως στη θύρα": "Which service usually listens on port",
  "καμία": "none",
  "Τι σημαίνει ένα πακέτο TCP με σημαίες": "What does a TCP packet with flags",
  "Η «χειραψία» TCP είναι SYN → SYN‑ACK → ACK. Παράξενοι συνδυασμοί (NULL, FIN, XMAS) δείχνουν εργαλεία σάρωσης όπως το nmap.": "The TCP “handshake” is SYN → SYN‑ACK → ACK. Odd combinations (NULL, FIN, XMAS) point to scanning tools like nmap.",
  "Άμυνα": "Defense",
  "Ορολογία": "Terminology",
