  "Από το δίκτυό σου": "From your network",
  "Πριν λίγο το NetWatch είδε": "A moment ago NetWatch saw",
  "Ποια τεχνική MITRE ATT&CK είναι;": "Which MITRE ATT&CK technique is it?",
