  "🎓 Σκορ": "🎓 Score",
  "Οι ερωτήσεις βγαίνουν από το υλικό του 📚 Μάθε και από τις πραγματικές ειδοποιήσεις του δικτύου σου.": "Questions come from the 📚 Learn material and from your network's real alerts.",
  "μηδενισμός": "reset",
  "ψάχνω στο NVD…": "searching NVD…",
  "⚖️ Μόνο στο δικό σου δίκτυο.": "⚖️ Only on your own network.",
  "Η σάρωση συσκευών που δεν σου ανήκουν χωρίς γραπτή άδεια είναι παράνομη. Ο σαρωτής δέχεται μόνο ιδιωτικές διευθύνσεις (192.168.x.x, 10.x.x.x).": "Scanning devices you don't own without written permission is illegal. The scanner only accepts private addresses (192.168.x.x, 10.x.x.x).",
  "σαρώνω…": "scanning…",
  "▶ Σάρωσε": "▶ Scan",
  "1 · Σάρωση του LAN σου": "1 · Scan your LAN",
  "Βρίσκει συσκευές, ανοιχτές θύρες, τι λογισμικό και ποια έκδοση τρέχουν (banner grabbing) και ελέγχει το TLS — όπως το": "Finds devices, open ports, what software and version they run (banner grabbing) and checks TLS — like",
  "χωρίς banner": "no banner",
  "καμία ανοιχτή θύρα από τις συνηθισμένες": "none of the usual ports open",
  "Τα αποτελέσματα μπήκαν και στην καρτέλα 🛡 Έλεγχος.": "The results were also added to the 🛡 Audit tab.",
  "ρωτάω το Shodan…": "asking Shodan…",
  "🌐 Έλεγχος έκθεσης": "🌐 Check exposure",
  "2 · Τι βλέπει το Internet για σένα": "2 · What the Internet sees about you",
  "Το κουμπί στέλνει τη δημόσια IP σου στο internetdb.shodan.io.": "The button sends your public IP to internetdb.shodan.io.",
  "✅ Το Shodan δεν βλέπει καμία ανοιχτή θύρα — ο router σου δεν εκθέτει τίποτα.": "✅ Shodan sees no open ports — your router exposes nothing.",
  "👉 Κλείσε στο router το port forwarding / UPnP / απομακρυσμένη διαχείριση που δεν χρειάζεσαι και κάνε ενημέρωση firmware.": "👉 On the router, turn off any port forwarding / UPnP / remote management you don't need and update the firmware.",
  "Κάνε μια επίθεση (🔴 red team) και δες αν την πιάνει η άμυνα (🔵 blue team). Τα πακέτα είναι": "Launch an attack (🔴 red team) and see if the defense catches it (🔵 blue team). The packets are",
  ": περνούν από την ίδια μηχανή ανίχνευσης αλλά δεν στέλνεται τίποτα στο δίκτυο. Δοκίμασε και την αθόρυβη εκδοχή — έτσι μαθαίνεις πώς ξεφεύγουν οι επιτιθέμενοι.": ": they go through the same detection engine but nothing is sent on the network. Try the stealthy version too — that's how you learn how attackers slip through.",
  "📢 θορυβώδες": "📢 noisy",
  "🤫 αθόρυβο": "🤫 stealthy",
  "⏳ εκτελείται…": "⏳ running…",
  "Ανιχνεύτηκε!": "Detected!",
  "Δεν ανιχνεύτηκε": "Not detected",
  "— ο «επιτιθέμενος» πέρασε απαρατήρητος.": "— the “attacker” went unnoticed.",
