  "Ταίριαξαν": "Matched",
  "πακέτα · θα έβγαζε": "packets · would raise",
  "ειδοποίηση(εις)": "alert(s)",
  "Μικρός αριθμός ειδοποιήσεων = καλός κανόνας. Πολλές = πιθανά false positives.": "Few alerts = good rule. Many = probably false positives.",
  "Οι κανόνες είναι απενεργοποιημένοι στο config.yaml (detectors.custom_rules).": "Rules are turned off in config.yaml (detectors.custom_rules).",
  "✎ στον editor": "✎ to editor",
  "Γράψε τον δικό σου κανόνα ανίχνευσης σε YAML, δοκίμασέ τον στην κίνηση που μόλις πέρασε και αποθήκευσέ τον — τρέχει αμέσως μαζί με τους ενσωματωμένους ανιχνευτές. Κάθε κανόνας εξάγεται και σε": "Write your own detection rule in YAML, test it on the traffic that just went by and save it — it runs right away alongside the built-in detectors. Every rule can also be exported as",
  "(για SIEM: Splunk, Elastic, Sentinel) και": "(for SIEMs: Splunk, Elastic, Sentinel) and",
