  "π.χ. T1046 (προαιρετικό)": "e.g. T1046 (optional)",
  "Διαγραφή του κανόνα": "Delete the rule",
  "από το rules/local.yaml;": "from rules/local.yaml?",
  "✔ αντιγράφηκε": "✔ copied",
  "Δεν βρέθηκαν επίπεδα — τρέξε": "No levels found — run",
  "live δίκτυο": "live network",
  "κανονικό": "normal",
  "Ο χάρτης και όλες οι καρτέλες δείχνουν τώρα το pcap του επιπέδου. Ερεύνησε: ⚠ Επιθέσεις, 📟 Συσκευές, 🔎 Λεπτομέρειες, 📦 Πακέτα, 🛡 Έλεγχος.": "The map and all tabs now show the level's pcap. Investigate: ⚠ Attacks, 📟 Devices, 🔎 Details, 📦 Packets, 🛡 Audit.",
  "Κάθε επίπεδο φορτώνει ένα pcap με μια «ιστορία». Ερεύνησέ το με τα εργαλεία του NetWatch σαν αναλυτής SOC και απάντησε στις ερωτήσεις. Η κανονική παρακολούθηση σταματά όσο παίζεις.": "Each level loads a pcap with a “story”. Investigate it with NetWatch's tools like a SOC analyst and answer the questions. Normal monitoring pauses while you play.",
