  "«Ξέχασε αυτό το δίκτυο»": "“Forget this network”",
  ", ώστε να μη συνδέεται αυτόματα (ούτε σε ψεύτικο με το ίδιο όνομα).": ", so it doesn't reconnect automatically (not even to a fake one with the same name).",
  "🔎 Ο έλεγχος μόνο διαβάζει — δεν αλλάζει ρυθμίσεις. Για να δουλέψει επικοινωνεί με: captive.apple.com (HTTP), DNS για one.one.one.one / dns.google / dns.quad9.net και ένα ανύπαρκτο .example, και TLS σε www.google.com, github.com, www.cloudflare.com. Σε live mode τρέχει αυτόματα κάθε φορά που αλλάζεις δίκτυο (απενεργοποίηση:": "🔎 The check only reads — it doesn't change settings. To work it contacts: captive.apple.com (HTTP), DNS for one.one.one.one / dns.google / dns.quad9.net and a non-existent .example, and TLS to www.google.com, github.com, www.cloudflare.com. In live mode it runs automatically every time you change networks (turn off:",
  "κανένας γνωστός tracker αυτή τη στιγμή": "no known trackers right now",
