  ": εταιρείες διαφημίσεων, analytics και τηλεμετρίας που μαζεύουν στοιχεία για το τι κάνεις.": ": advertising, analytics and telemetry companies that collect data about what you do.",
  "🔎 φίλτρο εφαρμογής/προορισμού": "🔎 filter app/destination",
