  "υπηρεσίες (SSH, Telnet, σελίδα router…) στον υπολογιστή σου. Κανείς νόμιμος δεν έχει λόγο να τις αγγίξει, οπότε": "services (SSH, Telnet, router page…) on your computer. No legitimate user has a reason to touch them, so",
  "όποιος συνδεθεί, σκανάρει ή δοκιμάζει κωδικούς": "anyone who connects, scans or tries passwords",
  "και σου βγάζω ειδοποίηση με το τι έστειλε. Δεν εκτελείται τίποτα: δείχνω ένα ψεύτικο μήνυμα, καταγράφω και κλείνω.": "and I alert you with what they sent. Nothing runs: I show a fake message, log it and close.",
