  "και": "and",
  "από τον κατασκευαστή της κάρτας δικτύου (MAC) και το όνομά τους — και με το ▶ Έλεγχος ψάχνω όλο το δίκτυό σου για": "by their network card maker (MAC) and their name — and with ▶ Check I search your whole network for",
  ", ό,τι μηχάνημα κι αν είναι (π.χ. VM). Ελέγχω τι αφήνουν ανοιχτό: Telnet, MQTT χωρίς κωδικό ή TLS, σελίδες χωρίς HTTPS… Δεν δοκιμάζω κωδικούς. Κάθε πρόβλημα έχει κουμπί για το μάθημα της 🎓 Ακαδημίας που δείχνει πώς φτιάχνεται.": ", whatever machine it runs on (e.g. a VM). I check what they leave open: Telnet, MQTT without a password or TLS, pages without HTTPS… I don't try passwords. Every problem has a button to the 🎓 Academy lesson that shows how to fix it.",
