  "Το WebRTC είναι κλειστό σε αυτόν τον browser — δεν μπορεί να διαρρεύσει IP.": "WebRTC is off in this browser — it can't leak an IP.",
  "Διαρροή: η IP μέσω WebRTC είναι διαφορετική από αυτή του VPN/Tor — ένα site μπορεί να μάθει την πραγματική σου σύνδεση.": "Leak: the IP via WebRTC is different from the VPN/Tor one — a site can learn your real connection.",
  "👉 Firefox: about:config → media.peerconnection.enabled = false · Chrome: επέκταση «WebRTC Leak Prevent» · ή χρησιμοποίησε Tor Browser.": "👉 Firefox: about:config → media.peerconnection.enabled = false · Chrome: the “WebRTC Leak Prevent” extension · or use Tor Browser.",
  "Η IP σου δείχνει ζώνη": "Your IP points to time zone",
  "Δεν ταιριάζουν: ένα site καταλαβαίνει ότι χρησιμοποιείς VPN και περίπου πού βρίσκεσαι πραγματικά.": "They don't match: a site can tell you're using a VPN and roughly where you really are.",
  "👉 Το Tor Browser δείχνει σε όλους UTC και αγγλικά, ώστε να μοιάζουν όλοι οι χρήστες ίδιοι.": "👉 Tor Browser shows UTC and English to everyone, so all users look the same.",
  "Ζώνη ώρας & γλώσσα": "Time zone & language",
  "Ο browser λέει: ζώνη": "The browser says: time zone",
  ", γλώσσες": ", languages",
