  "Στο Tor καμία ενδιάμεση θέση δεν ξέρει ταυτόχρονα": "On Tor no point along the way knows both",
  "είσαι και": "you are and",
  "πού": "where",
  "πας (3 κόμβοι, κρυπτογράφηση σε στρώσεις — «κρεμμύδι»). Το VPN απλώς μεταφέρει την εμπιστοσύνη από τον πάροχο Internet στον πάροχο VPN. Κανένα από τα δύο δεν σε κρύβει αν συνδεθείς στον λογαριασμό σου (Google, Instagram…).": "you're going (3 nodes, layered encryption — an “onion”). A VPN just moves your trust from the Internet provider to the VPN provider. Neither hides you if you log in to your account (Google, Instagram…).",
  "🧅 Tor στο Mac": "🧅 Tor on the Mac",
  ": ανώνυμο web — άνοιξέ το και πάτα ξανά «Έλεγχος»· το NetWatch το βλέπει στη θύρα 9150 και δείχνει την IP εξόδου.": ": anonymous web — open it and press “Check” again; NetWatch sees it on port 9150 and shows the exit IP.",
  "Όλες οι εφαρμογές": "All apps",
  "→ SOCKS proxy στη θύρα 9050 (π.χ.": "→ SOCKS proxy on port 9050 (e.g.",
  "Στο ⚠ Επιθέσεις, σε live με VPN, το NetWatch ειδοποιεί όταν DNS ή IPv6 βγαίνουν έξω από το τούνελ.": "In ⚠ Attacks, in live mode with a VPN, NetWatch alerts you when DNS or IPv6 leaks outside the tunnel.",
  "🔎 Ο έλεγχος τρέχει μόνο όταν πατήσεις το κουμπί και επικοινωνεί με: api.ipify.org / api64.ipify.org (IP), ip-api.com (τοποθεσία/πάροχος), check.torproject.org, bash.ws (DNS leak test) και stun.l.google.com (WebRTC, από τον browser).": "🔎 The check only runs when you press the button and contacts: api.ipify.org / api64.ipify.org (IP), ip-api.com (location/provider), check.torproject.org, bash.ws (DNS leak test) and stun.l.google.com (WebRTC, from the browser).",
  "🧭 Από πού ξεκινάω;": "🧭 Where do I start?",
  "Ακολούθησε τα βήματα με τη σειρά. Κάθε κουμπί σε πάει στη σωστή καρτέλα· εκεί, κάθε ειδοποίηση έχει «Πες μου περισσότερα» με εξήγηση.": "Follow the steps in order. Each button takes you to the right tab; there, every alert has “Tell me more” with an explanation.",
  "δεν έχει ελεγχθεί ακόμα": "not checked yet",
  "Εκεί: κρυπτογράφηση, ψεύτικα δίκτυα (evil twin), DNS/TLS παγίδες, firewall & VPN του Mac — με οδηγίες διόρθωσης.": "There: encryption, fake networks (evil twin), DNS/TLS traps, the Mac's firewall & VPN — with how-to-fix steps.",
  "Μου επιτίθεται κάποιος τώρα;": "Is someone attacking me right now?",
  "🟢 τίποτα ύποπτο": "🟢 nothing suspicious",
  "Εκεί: κάθε ειδοποίηση λέει με απλά λόγια αν είναι κακό και τι να κάνεις. «Ποιος είναι;» → όλα για την IP.": "There: every alert says in plain words whether it's bad and what to do. “Who is it?” → everything about the IP.",
  "Ποιος είναι στο δίκτυό μου;": "Who is on my network?",
  "— τις αναγνωρίζεις;": "— do you recognize them?",
  "Εκεί: κάθε συσκευή με MAC, κατασκευαστή, τι κάνει. Και στο κουτί «🏠 Το δίκτυό σου» κάτω αριστερά στον χάρτη.": "There: every device with its MAC, maker, what it does. Also in the “🏠 Your network” box at the bottom left of the map.",
  "Πού πάει η κίνησή μου;": "Where does my traffic go?",
  "🛣 Διαδρομή": "🛣 Route",
  "Παρακάτω: διάλεξε ένα site και δες βήμα-βήμα από πού περνά και ποιος βλέπει τι.": "Below: pick a site and see step by step where it passes and who sees what.",
  "Φαίνομαι στο Internet;": "Am I visible on the Internet?",
  "πάτα «Έλεγχος διαρροών»": "press “Leak check”",
  "Εκεί: τι ξέρει κάθε site για σένα, Tor/VPN, διαρροές DNS / IPv6 / WebRTC.": "There: what every site knows about you, Tor/VPN, DNS / IPv6 / WebRTC leaks.",
  "Πόσο ασφαλές είναι το σπίτι μου;": "How safe is my home?",
  "βαθμός": "score",
  "υπολογίζεται…": "calculating…",
  "Εκεί: κωδικοί χωρίς κρυπτογράφηση, επικίνδυνες υπηρεσίες στο LAN, τι να διορθώσεις.": "There: unencrypted passwords, risky services on the LAN, what to fix.",
  "Θέλω να μάθω / να εξασκηθώ": "I want to learn / practice",
  "Σειρά: 🎓 Ακαδημία (CCNA από το μηδέν & IoT security με ESP32/Raspberry Pi, με animations και labs) → ❓ Κουίζ → 🔴 Pentest (σκάναρε το δίκτυό σου, purple-team lab) → 🧩 Κανόνες → 🚩 CTF.": "Order: 🎓 Academy (CCNA from scratch & IoT security with ESP32/Raspberry Pi, with animations and labs) → ❓ Quiz → 🔴 Pentest (scan your network, purple-team lab) → 🧩 Rules → 🚩 CTF.",
  "🛣 Πού πάει η κίνησή σου — βήμα-βήμα": "🛣 Where your traffic goes — step by step",
  "Δεν υπάρχει ακόμα κίνηση προς το Internet.": "No traffic to the Internet yet.",
  "📡 Δείξε όλους τους routers στη διαδρομή (traceroute)": "📡 Show all routers on the route (traceroute)",
  "⏳ traceroute… (έως 20 δευτ.)": "⏳ traceroute… (up to 20 sec)",
  "* (δεν απαντά)": "* (no reply)",
  "· ιδιωτική (σπίτι ή δίκτυο παρόχου)": "· private (home or provider network)",
  "Τα τελευταία βήματα δεν απαντούν — πολλοί servers (π.χ. GitHub) μπλοκάρουν το traceroute. Συνηθισμένο.": "The last hops don't reply — many servers (e.g. GitHub) block traceroute. That's normal.",
  "Διάλεξε προορισμό (ή κάνε κλικ σε σημείο στον χάρτη):": "Pick a destination (or click a point on the map):",
  "· δημόσια IP": "· public IP",
  "Εδώ ξεκινά: ο browser ή μια εφαρμογή θέλει να μιλήσει με το": "It starts here: the browser or an app wants to talk to",
  "στο Internet": "on the Internet",
