  "Καθυστέρηση & απώλειες (SmokePing)": "Latency & loss (SmokePing)",
  "Κάθε 60″ στέλνω 10 ping σε κάθε στόχο και κρατάω 30 μέρες ιστορικό. Ο «καπνός» είναι το εύρος min–max, η γραμμή ο διάμεσος (πράσινη = χωρίς απώλειες, πορτοκαλί/κόκκινη = απώλειες). Ιδανικό για να αποδείξεις στον πάροχο ότι «κάθε βράδυ αργεί».": "Every 60″ I send 10 pings to each target and keep 30 days of history. The “smoke” is the min–max range, the line is the median (green = no loss, orange/red = loss). Perfect for proving to your ISP that “it's slow every evening”.",
  "Καμία ώρα της μέρας δεν ξεχωρίζει — η σύνδεση είναι σταθερή όλο το 24ωρο.": "No hour of the day stands out — the connection is stable around the clock.",
  "Δεν υπάρχει ακόμη αρκετό ιστορικό.": "Not enough history yet.",
  "Πάροχος (1ο δημόσιο hop)": "ISP (1st public hop)",
  "σάρωση… (5–10″)": "scanning… (5–10″)",
  "προτεινόμενο": "recommended",
  "το δικό σου": "yours",
  "Τα ονόματα των δικτύων (SSID) είναι κρυμμένα από το macOS. Δώσε άδεια «Υπηρεσίες τοποθεσίας» στο Terminal ή στο NetWatch (Ρυθμίσεις συστήματος → Απόρρητο και ασφάλεια → Υπηρεσίες τοποθεσίας) για να φαίνονται.": "Network names (SSIDs) are hidden by macOS. Grant “Location Services” to Terminal or NetWatch (System Settings → Privacy & Security → Location Services) to see them.",
  "Παράθυρα συντήρησης, κανάλια ειδοποιήσεων, εξαγωγή μετρικών για Grafana και καταγραφή πακέτων γύρω από κάθε ειδοποίηση — τα «εργαλεία βάρδιας» ενός NOC.": "Maintenance windows, notification channels, metrics export for Grafana and packet capture around every alert — a NOC's “shift tools”.",
  "Συντήρηση": "Maintenance",
  "καμία τώρα": "none now",
  "Όσο τρέχει, οι ειδοποιήσεις φαίνονται εδώ αλλά": "While it runs, alerts show up here but are",
  "δεν": "not",
  "στέλνονται στο κινητό και δεν τρέχουν playbooks — για backups, αναβαθμίσεις ή τις δικές σου δοκιμές.": "sent to your phone and playbooks don't run — for backups, upgrades or your own tests.",
