  "(δεν ανεβαίνει ποτέ στο git).": "(never pushed to git).",
  "Πακέτα/s, κίνηση, hosts, ειδοποιήσεις ανά σοβαρότητα, homelab up/latency, ping (SmokePing) και αν τρέχει συντήρηση — σε μορφή Prometheus.": "Packets/s, traffic, hosts, alerts by severity, homelab up/latency, ping (SmokePing) and whether maintenance is running — in Prometheus format.",
