  "(🇩🇪 Γερμανία). Ο guard αλλάζει μόνο κάθε λίγους μήνες — έτσι δυσκολεύει μια παρακολούθηση.": "(🇩🇪 Germany). The guard changes only every few months — that makes tracking harder.",
  "Το NetWatch διαβάζει μόνο (ControlPort σε localhost) — δεν στέλνει και δεν αλλάζει τίποτα. Η «Νέα ταυτότητα» (NEWNYM) ζητά από το Tor καινούργιο κύκλωμα, όπως το κουμπί στο Tor Browser.": "NetWatch only reads (ControlPort on localhost) — it sends and changes nothing. \"New identity\" (NEWNYM) asks Tor for a fresh circuit, like the button in Tor Browser.",
