  "(ιδιωτικές IP) για κάμερες/DVR με ανοιχτό stream, UI χωρίς κωδικό, παλιό firmware ή P2P cloud — και λέει πώς να τα κλείσεις.": "(private IPs) for cameras/DVRs with an open stream, a no-password UI, old firmware or P2P cloud — and tells you how to close them.",
