  "Φέρνει τις ειδοποιήσεις από": "Brings alerts from",
  "(notice/weird logs) μέσα στο NetWatch, στον ίδιο κατάλογο επιθέσεων. Ρύθμισε αρχεία στο": "(notice/weird logs) into NetWatch, in the same attack list. Configure files in",
  "ή ανέβασε ένα εδώ:": "or upload one here:",
  "Ανέβασε eve.json ή Zeek log": "Upload eve.json or a Zeek log",
  "Πιστοποιητικά — Certificate Transparency": "Certificates — Certificate Transparency",
  "Κάθε πιστοποιητικό TLS καταγράφεται δημόσια (Certificate Transparency). Αν κάποιος εκδώσει πιστοποιητικό για το domain σου (π.χ. phishing ή παραβίαση), θα φανεί εδώ. Πηγή: crt.sh.": "Every TLS certificate is logged publicly (Certificate Transparency). If someone issues a certificate for your domain (e.g. phishing or a breach), it shows up here. Source: crt.sh.",
  "Έλεγχος τώρα": "Check now",
  "Ποιος browser, ποια έκδοση, ποιο λειτουργικό. Ανεβαίνει με κάθε ενημέρωση — συνδυασμένο με τα υπόλοιπα, σε ξεχωρίζει.": "Which browser, version and OS. It changes with every update — combined with the rest, it singles you out.",
  "Ποιες γραμματοσειρές έχεις εγκατεστημένες (μετριέται το πλάτος του κειμένου).": "Which fonts you have installed (measured by text width).",
  "Ζωγραφίζω αόρατα κείμενο και σχήματα: η κάρτα γραφικών, οι γραμματοσειρές και το antialiasing δίνουν ελάχιστα διαφορετικά pixels σε κάθε υπολογιστή.": "I draw text and shapes invisibly: the GPU, fonts and antialiasing give slightly different pixels on each computer.",
  "Το όνομα της κάρτας γραφικών σου, όπως το δίνει ο driver.": "The name of your GPU, as the driver reports it.",
  "Η σειρά των γλωσσών (π.χ. el-GR, en) είναι σπάνια εκτός Ελλάδας.": "The order of languages (e.g. el-GR, en) is rare outside Greece.",
  "Ένας αόρατος ήχος περνά από τον επεξεργαστή ήχου· το αποτέλεσμα διαφέρει ελάχιστα ανά σύστημα.": "An inaudible sound passes through the audio processor; the result differs slightly per system.",
  "Ανάλυση, πυκνότητα (Retina) και βάθος χρώματος.": "Resolution, density (Retina) and colour depth.",
  "Λέει περίπου πού βρίσκεσαι, ακόμα και πίσω από VPN.": "Hints at roughly where you are, even behind a VPN.",
  "Πόσους πυρήνες και (σε Chrome) πόση μνήμη έχει ο υπολογιστής.": "How many cores and (in Chrome) how much memory the computer has.",
  "Mac / Windows / Linux / κινητό, και αν έχει οθόνη αφής.": "Mac / Windows / Linux / mobile, and whether it has a touchscreen.",
  "Σκούρο θέμα, λιγότερη κίνηση, Do Not Track… Ειρωνικά, το DNT κάνει τον browser πιο σπάνιο.": "Dark theme, reduced motion, Do Not Track… Ironically, DNT makes the browser rarer.",
  "Μικρές λεπτομέρειες που προσθέτουν λίγα bits η καθεμιά.": "Small details that each add a few bits.",
