  "uc-httpd (Sofia/XMeye) — γνωστές ευπάθειες (π.χ. path traversal, CVE-2018-9995)": "uc-httpd (Sofia/XMeye) — known vulnerabilities (e.g. path traversal, CVE-2018-9995)",
  "Sofia / XMeye DVR (ιδιόκτητο)": "Sofia / XMeye DVR (proprietary)",
  "Το web UI στη θύρα 80 απαντά 200 OK ΧΩΡΙΣ να ζητά κωδικό — οποιοσδήποτε στο δίκτυο βλέπει τη ροή/τις ρυθμίσεις.": "The web UI on port 80 answers 200 OK WITHOUT asking for a password — anyone on the network sees the stream/settings.",
