  "Τι βοηθά:": "What helps:",
  "Tor Browser (όλοι ίδιοι: ίδιο μέγεθος παραθύρου, UTC, αγγλικά) · Firefox με": "Tor Browser (everyone identical: same window size, UTC, English) · Firefox with",
  "Brave (θόρυβος στο canvas/audio) · Safari (κρύβει μέρος των γραμματοσειρών). Τα blockers διαφημίσεων": "Brave (noise on canvas/audio) · Safari (hides some fonts). Ad blockers",
  "βοηθούν εδώ — συχνά σε κάνουν πιο σπάνιο.": "help here — they often make you rarer.",
  "Ενημέρωσε το firmware της κάμερας/καταγραφικού στην τελευταία έκδοση.": "Update the camera/recorder firmware to the latest version.",
  "Άλλαξε τον προεπιλεγμένο κωδικό (admin/12345) — έλεγξέ τον χειροκίνητα, δεν τον δοκιμάζει το εργαλείο.": "Change the default password (admin/12345) — check it manually, the tool doesn't try it.",
  "Άλλαξε τον χειροκίνητα, δεν τον δοκιμάζει το εργαλείο.": "Change it manually, the tool doesn't try it.",
  "Απενεργοποίησε το P2P cloud (XMeye, iCloud-cam κ.λπ.) — στέλνει το βίντεο σε άγνωστους διακομιστές.": "Disable the P2P cloud (XMeye, iCloud-cam, etc.) — it sends the video to unknown servers.",
  "Βάλε τις κάμερες σε χωριστό VLAN/SSID ή πίσω από VPN — όχι στο ίδιο δίκτυο με τον υπολογιστή σου.": "Put the cameras on a separate VLAN/SSID or behind a VPN — not on the same network as your computer.",
  "Κλείσε το UPnP στο router και σβήσε κάθε port-forward προς την κάμερα (μην τη βγάζεις στο Internet).": "Turn off UPnP on the router and remove any port-forward to the camera (don't expose it to the Internet).",
  "Χρησιμοποίησε HTTPS με σύγχρονο TLS (1.2+) αντί για απλό HTTP στο web UI.": "Use HTTPS with modern TLS (1.2+) instead of plain HTTP on the web UI.",
  "Web UI σε απλό HTTP (θύρα 80) — αν κάνεις login, ο κωδικός ταξιδεύει ανοιχτός.": "Web UI over plain HTTP (port 80) — if you log in, the password travels in the clear.",
  "Θύρα 34567 (Sofia / XMeye DVR (ιδιόκτητο)): ιδιόκτητο DVR με P2P cloud (XMeye/iCloud-cam) — συχνά στέλνει βίντεο έξω χωρίς να το ξέρεις.": "Port 34567 (Sofia / XMeye DVR (proprietary)): proprietary DVR with P2P cloud (XMeye/iCloud-cam) — often sends video out without you knowing.",
  "Θύρα 443 (Web UI κάμερας (HTTPS)) προσβάσιμη αλλά ζητά κωδικό — καλό.": "Port 443 (Camera web UI (HTTPS)) reachable but asks for a password — good.",
  "Θύρα 554 (RTSP (ροή βίντεο)) προσβάσιμη αλλά ζητά κωδικό — καλό.": "Port 554 (RTSP (video stream)) reachable but asks for a password — good.",
  "Θύρα 80: Boa webserver — εγκαταλελειμμένος, με γνωστές ευπάθειες": "Port 80: Boa webserver — abandoned, with known vulnerabilities",
  "Θύρα 80: uc-httpd (Sofia/XMeye) — γνωστές ευπάθειες (π.χ. path traversal, CVE-2018-9995)": "Port 80: uc-httpd (Sofia/XMeye) — known vulnerabilities (e.g. path traversal, CVE-2018-9995)",
  "Ακόμα και χωρίς cookies και με VPN, ένα site μπορεί να σε αναγνωρίσει από τον": "Even without cookies and with a VPN, a site can recognise you from the",
  "Ο έλεγχος τρέχει μόνο όταν πατήσεις το κουμπί και επικοινωνεί με: api.ipify.org / api64.ipify.org (IP), ip-api.com (τοποθεσία/πάροχος), check.torproject.org, bash.ws (DNS leak test), whoami.akamai.net (resolver χωρίς τρίτους) και stun.l.google.com (WebRTC, από τον browser).": "The check runs only when you press the button and contacts: api.ipify.org / api64.ipify.org (IP), ip-api.com (location/ISP), check.torproject.org, bash.ws (DNS leak test), whoami.akamai.net (resolver without third parties) and stun.l.google.com (WebRTC, from the browser).",
  "Δεν ελέγχθηκε": "Not checked",
