  "Δες βήμα-βήμα τι ανταλλάσσουν οι συσκευές — και ακριβώς από κάτω, το αληθινό αντίστοιχο από το δικό σου δίκτυο.": "See step by step what devices exchange — and right below, the real thing from your own network.",
