  "Κανένα handshake: κάθε γραμμή είναι ένα μεμονωμένο datagram.": "No handshake: each line is a standalone datagram.",
  "Κάτω από 3 ms = ήταν στην cache του resolver· δεκάδες ms = έγινε ολόκληρη η αναζήτηση.": "Under 3 ms = it was in the resolver’s cache; tens of ms = a full lookup happened.",
