  "WireGuard στο σπίτι": "WireGuard at home",
  "Αξιόπιστη σύνδεση: πρώτα «χειραψία» 3 βημάτων, μετά αριθμημένα δεδομένα με επιβεβαιώσεις, και στο τέλος κλείσιμο.": "A reliable connection: first a 3-step “handshake”, then numbered data with acknowledgements, and finally a close.",
  "Χωρίς σύνδεση και χωρίς επιβεβαιώσεις: στέλνεις και ελπίζεις. Γρήγορο, γι’ αυτό το χρησιμοποιούν DNS, παιχνίδια, κλήσεις, QUIC.": "No connection and no acknowledgements: send and hope. Fast, which is why DNS, games, calls and QUIC use it.",
  "Ο «τηλεφωνικός κατάλογος» του internet: μετατρέπει ονόματα (example.com) σε διευθύνσεις IP, ρωτώντας μια ιεραρχία από servers.": "The internet’s “phone book”: turns names (example.com) into IP addresses by asking a hierarchy of servers.",
  "Πώς παίρνει IP μια συσκευή μόλις μπει στο Wi-Fi: 4 μηνύματα, D-O-R-A.": "How a device gets an IP as soon as it joins Wi‑Fi: 4 messages, D-O-R-A.",
  "Στο τοπικό δίκτυο τα πακέτα πάνε σε MAC, όχι σε IP. Το ARP βρίσκει «ποια MAC έχει αυτή την IP».": "On the local network packets go to a MAC, not an IP. ARP finds “which MAC has this IP”.",
  "Τα «μηνύματα ελέγχου» του IP. Το ping στέλνει Echo Request και περιμένει Echo Reply, για να μετρήσει αν απαντά κάποιος και πόσο γρήγορα.": "IP’s “control messages”. Ping sends an Echo Request and waits for an Echo Reply, to measure whether someone answers and how fast.",
  "Ποιοι routers είναι ανάμεσα σε σένα και τον προορισμό; Ένα έξυπνο κόλπο με το TTL.": "Which routers sit between you and the destination? A clever trick with the TTL.",
  "Η κρυπτογράφηση πίσω από το λουκέτο του HTTPS. Στην έκδοση 1.3 χρειάζεται μόλις 1 πήγαινε-έλα, πάνω από μια ήδη ανοιχτή σύνδεση TCP.": "The encryption behind the HTTPS padlock. Version 1.3 needs just 1 round trip, on top of an already open TCP connection.",
  "Αίτημα και απάντηση, σε απλό κείμενο. Χωρίς το «S» όλα ταξιδεύουν ορατά — και αυτό ακριβώς βλέπεις εδώ.": "Request and response, in plain text. Without the “S” everything travels in the clear — and that’s exactly what you see here.",
  "Όλες οι συσκευές του σπιτιού βγαίνουν στο internet με ΜΙΑ δημόσια IP. Ο router σημειώνει ποιος ρώτησε τι.": "All the devices at home go out to the internet with ONE public IP. The router notes who asked for what.",
  "Το νέο «TCP + TLS σε ένα», πάνω από UDP. Το χρησιμοποιούν Google, YouTube, Cloudflare. Ξεκινά σε 1 πήγαινε-έλα αντί για 2.": "The new “TCP + TLS in one”, over UDP. Used by Google, YouTube, Cloudflare. It starts in 1 round trip instead of 2.",
  "Ασφαλές τερματικό σε απομακρυσμένο μηχάνημα (Raspberry Pi, Proxmox, server). Πρώτα κλειδιά, μετά ταυτότητα, μετά shell.": "A secure terminal on a remote machine (Raspberry Pi, Proxmox, server). Keys first, then identity, then a shell.",
  "Το πρωτόκολλο των έξυπνων συσκευών: οι αισθητήρες «δημοσιεύουν» σε θέματα (topics), ο broker τα μοιράζει σε όποιον έχει «εγγραφεί».": "The smart-device protocol: sensors “publish” to topics, and the broker hands them to whoever has “subscribed”.",
  "Σύγχρονο, μικρό και γρήγορο VPN. Χειραψία σε 1 RTT, και μετά όλη η κίνηση πάει κρυπτογραφημένη σε ένα «τούνελ».": "A modern, small, fast VPN. Handshake in 1 RTT, then all traffic travels encrypted in a “tunnel”.",
