  "Κρατά ανοιχτή την αντιστοίχιση NAT του router. ℹ Σε άγνωστους ο WireGuard δεν απαντά καθόλου: για έναν scanner η θύρα μοιάζει κλειστή.": "It keeps the router’s NAT mapping open. ℹ WireGuard doesn’t answer strangers at all: to a scanner the port looks closed.",
