  "Κόψε και την επικοινωνία με άλλες συσκευές του LAN (εκτός από όσες έμαθε)": "Also block traffic to other LAN devices (except the ones it learned)",
  "Επιτρέπει μόνο τις IP του προφίλ + DNS προς τον router, και κόβει ό,τι άλλο πάει στο internet. Βάλε πρώτα": "Allows only the profile's IPs + DNS to the router, and drops everything else going to the internet. First give the device a",
  "σταθερή IP (DHCP reservation)": "fixed IP (DHCP reservation)",
  "στη συσκευή. Το NetWatch ΔΕΝ αγγίζει τον router — αντιγράφεις και επικολλάς εσύ.": ". NetWatch does NOT touch the router — you copy and paste.",
