  "Ένας προσομοιωτής Cisco IOS: γράφεις τις ίδιες εντολές με έναν πραγματικό router/switch, και το NetWatch υπολογίζει αν περνά το ping. «?» για βοήθεια, Tab για συμπλήρωση, ↑↓ για ιστορικό.": "A Cisco IOS simulator: you type the same commands as on a real router/switch, and NetWatch works out whether the ping gets through. «?» for help, Tab to complete, ↑↓ for history.",
