  "MAC με SHA-1 (ακόμα ασφαλές ως HMAC, αλλά παλιό)": "MAC with SHA-1 (still safe as HMAC, but dated)",
  "Ανταλλαγή κλειδιών με SHA-1": "Key exchange with SHA-1",
