  "Ό,τι κάνεις στην κάμερα καταγράφεται — έτσι θα έβλεπε την επίθεσή σου ένα SOC. Οι brute-force και οι επιτυχείς συνδέσεις βγάζουν και ειδοποίηση (σημειωμένη «lab»).": "Everything you do to the camera is logged — this is how a SOC would see your attack. Brute force and successful logins also raise an alert (marked «lab»).",
