  "συσκευών και βαθμολογεί A–F: παλιές εκδόσεις TLS, ληγμένα ή αυτο-υπογεγραμμένα πιστοποιητικά, αδύναμοι αλγόριθμοι SSH, γνωστά CVE (Terrapin, regreSSHion).": "devices and grades them A–F: old TLS versions, expired or self-signed certificates, weak SSH algorithms, known CVEs (Terrapin, regreSSHion).",
