  "30 θύρες UDP σε ~1,5 s": "30 UDP ports in ~1.5 s",
  "40 θύρες σε ~2 δευτερόλεπτα": "40 ports in ~2 seconds",
  "12 θύρες UDP, μία κάθε 1,5 s": "12 UDP ports, one every 1.5 s",
  "ARP «ποιος έχει;» για 60 διευθύνσεις σε ~2,5 s": "ARP «who-has?» for 60 addresses in ~2.5 s",
  "ARP για 40 διευθύνσεις, μία κάθε 0,6 s": "ARP for 40 addresses, one every 0.6 s",
  "netdiscover -p με καθυστέρηση": "netdiscover -p with delay",
  "μολυσμένη κάμερα σαρώνει 23/2323 σε 30 συσκευές και δοκιμάζει 16 κωδικούς Telnet σε εσένα": "an infected camera scans 23/2323 on 30 devices and tries 16 Telnet passwords on you",
  "σάρωση 23/2323 μία συσκευή κάθε 2,5 s και 6 αργές δοκιμές κωδικού": "scans 23/2323 one device every 2.5 s with 6 slow password attempts",
  "σύνδεση FTP (USER/PASS) και συνεδρία Telnet που «ακούει» ο επιτιθέμενος": "an FTP login (USER/PASS) and a Telnet session the attacker «listens» to",
  "DHCP starvation (30 DISCOVER με τυχαίες MAC) και 3 ψεύτικες προσφορές": "DHCP starvation (30 DISCOVERs with random MACs) and 3 fake offers",
  "35 ερωτήματα με τυχαία hex subdomains": "35 queries with random hex subdomains",
  "δεδομένα κωδικοποιημένα": "encoded data",
  "10 συνδέσεις HTTPS στον C2 ακριβώς κάθε 60 s": "10 HTTPS connections to the C2 exactly every 60 s",
  "jitter 1%": "jitter 1%",
  "10 συνδέσεις κάθε ~60 s με jitter 50%": "10 connections every ~60 s with 50% jitter",
  "20 ερωτήματα για «τυχαία» domains": "20 queries for «random» domains",
  "π.χ. xk3j9qz7lpwt.com) που δεν υπάρχουν (NXDOMAIN": "e.g. xk3j9qz7lpwt.com) that don't exist (NXDOMAIN",
  "20 ανύπαρκτα domains από λέξεις λεξικού": "20 non-existent domains made of dictionary words",
  "π.χ. lightriverhouse.net — τύπου Suppobox": "e.g. lightriverhouse.net — Suppobox style",
  "150 ping προς εσένα σε 1,5 s": "150 pings at you in 1.5 s",
  "100 ping προς εσένα σε 5 s": "100 pings at you in 5 s",
  "≥ 100 ping προς εσένα σε 5 s": "≥ 100 pings at you in 5 s",
  "Η σάρωση UDP είναι αργή και αναξιόπιστη για τον επιτιθέμενο (δεν υπάρχει χειραψία), αλλά βρίσκει υπηρεσίες που ξεχνάμε: SNMP, TFTP, UPnP. Ίδιο μάθημα με το TCP: κάτω από το όριο δεν φαίνεται.": "UDP scanning is slow and unreliable for the attacker (no handshake), but it finds services we forget: SNMP, TFTP, UPnP. Same lesson as TCP: below the threshold it's invisible.",
  "Το ARP δεν φιλτράρεται από firewall και κάθε συσκευή πρέπει να απαντήσει — γι' αυτό είναι ο πιο αξιόπιστος τρόπος ανακάλυψης στο LAN. Αργή σάρωση μοιάζει με κανονική κίνηση.": "ARP isn't filtered by firewalls and every device must answer — that's why it's the most reliable discovery method on a LAN. A slow scan looks like normal traffic.",
  "Το Mirai μολύνει κάμερες/routers με εργοστασιακούς κωδικούς Telnet (admin/admin, root/xc3511) και μετά σαρώνει για νέα θύματα. Άμυνα: κλείσε το Telnet, άλλαξε κωδικούς, απομόνωσε τα IoT σε VLAN.": "Mirai infects cameras/routers with factory Telnet passwords (admin/admin, root/xc3511) and then scans for new victims. Defence: turn off Telnet, change passwords, isolate IoT in a VLAN.",
  "Ο επιτιθέμενος που «ακούει» είναι παθητικός — δεν τον βλέπεις. Αυτό που ΜΠΟΡΕΙΣ να δεις είναι ότι ένας κωδικός ταξίδεψε ανοιχτά. Η μόνη πραγματική άμυνα είναι η κρυπτογράφηση (SFTP, SSH, HTTPS).": "An attacker who «listens» is passive — you can't see them. What you CAN see is that a password travelled in the clear. The only real defence is encryption (SFTP, SSH, HTTPS).",
  "Όποιος απαντήσει πρώτος στο DHCP ορίζει gateway και DNS της συσκευής — τέλειο MITM. Δεν υπάρχει αθόρυβος τρόπος: η ψεύτικη απάντηση πρέπει να σταλεί. Άμυνα: DHCP snooping στο switch.": "Whoever answers DHCP first sets the device's gateway and DNS — a perfect MITM. There's no quiet way: the fake reply has to be sent. Defence: DHCP snooping on the switch.",
  "Το malware «ρωτάει» τον αφέντη του για εντολές σε τακτά διαστήματα· το σταθερό «ρολόι» το προδίδει. Τα σύγχρονα C2 προσθέτουν τυχαίο jitter ώστε τα διαστήματα να μη μοιάζουν μηχανικά — τότε χρειάζεται στατιστική ανάλυση σε ώρες/μέρες (π.χ. RITA) και όχι σε λίγα λεπτά.": "Malware «asks» its master for commands at regular intervals; the steady «clock» gives it away. Modern C2s add random jitter so the intervals don't look mechanical — then you need statistics over hours/days (e.g. RITA), not a few minutes.",
  "Το malware δοκιμάζει εκατοντάδες ονόματα μέχρι να βρει αυτό που έχει καταχωρίσει ο επιτιθέμενος. Τα «τυχαία» ονόματα φαίνονται από τη στατιστική των γραμμάτων· τα DGA από λέξεις λεξικού μοιάζουν ανθρώπινα και ξεφεύγουν — εκεί βοηθά η φήμη/ηλικία του domain.": "Malware tries hundreds of names until it hits the one the attacker registered. «Random» names stand out by letter statistics; dictionary-word DGAs look human and slip through — there, domain reputation/age helps.",
  "Όπως κάθε DoS, ο όγκος είναι ο σκοπός και άρα φαίνεται αμέσως. Άμυνα: όριο ICMP στο router.": "Like any DoS, volume is the point, so it shows immediately. Defence: ICMP rate limit on the router.",
