  "ψάξε ενεργά ό,τι έμεινε κάτω από τα όρια": "actively look for what stayed below the thresholds",
  "Σαν το": "Like",
  "ενός SOC: οι ειδοποιήσεις του ίδιου «δράστη» μέσα σε 30′ μαζεύονται σε μία υπόθεση. Τη διαλέγεις (νέα → υπό έρευνα → επιλύθηκε), κρατάς σημειώσεις, και αν ήταν ψευδώς θετικό, το NetWatch δεν θα ξαναχτυπήσει για το ίδιο πράγμα (για όσο ορίσεις).": "in a SOC: alerts from the same «actor» within 30′ are grouped into one case. You triage it (new → investigating → resolved), keep notes, and if it was a false positive, NetWatch won't fire again for the same thing (for as long as you choose).",
